class Solution { fun getBiggestThree(grid:Array<IntArray>):IntArray{val rows=grid.size;val cols=grid[0].size;val sums=java.util.TreeSet<Int>(compareByDescending{it});for(row in 0 until rows)for(col in 0 until cols){sums.add(grid[row][col]);var radius=1;while(row+2*radius<rows&&col-radius>=0&&col+radius<cols){var sum=0;for(step in 0 until radius)sum+=grid[row+step][col+step]+grid[row+radius+step][col+radius-step]+grid[row+2*radius-step][col-step]+grid[row+radius-step][col-radius+step];sums.add(sum);radius++}};return sums.take(3).toIntArray()} }
